import{_ as h,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Scaffolding","description":"","frontmatter":{},"headers":[],"relativePath":"learning/scaffolding.md","filePath":"learning/scaffolding.md"}'),g={name:"learning/scaffolding.md"};function c(o,n,r,l,e,m){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="scaffolding" tabindex="-1">Scaffolding <a class="header-anchor" href="#scaffolding" aria-label="Permalink to &quot;Scaffolding&quot;">​</a></h1><p>Trên trang này# Scaffolding — bắc giàn giáo <a href="#scaffolding-—-bac-gian-giao">​</a> Scaffolding là hỗ trợ tạm thời, được thiết kế để <strong>gỡ dần đi</strong>. Nếu nó không được gỡ, nó không còn là scaffolding — nó thành cây nạng. Hình ảnh gốc rất đúng: giàn giáo dựng quanh một toà nhà đang xây. Nó thiết yếu trong lúc xây, nhưng nếu toà nhà xong mà giàn giáo vẫn còn thì có gì đó sai. Trong việc học cũng vậy — mục tiêu cuối cùng luôn là learner làm được <strong>một mình</strong>.</p><h2 id="van-đe-ma-scaffolding-giai-​" tabindex="-1">Vấn đề mà scaffolding giải <a href="#van-đe-ma-scaffolding-giai">​</a> <a class="header-anchor" href="#van-đe-ma-scaffolding-giai-​" aria-label="Permalink to &quot;Vấn đề mà scaffolding giải [​](#van-đe-ma-scaffolding-giai)&quot;">​</a></h2><p>Có một khoảng cách giữa thứ learner làm được một mình và thứ learner làm được khi có người hỗ trợ đúng chỗ. Việc học hiệu quả nhất xảy ra <strong>trong khoảng cách đó</strong> — không phải ở dưới (quá dễ, không học được gì) và không phải ở trên (quá khó, chỉ tạo ra thất bại và nản). Khoảng cách này khác nhau ở từng đứa trẻ và <strong>khác nhau ở từng chủ đề trong cùng một đứa trẻ</strong>. Đây là lý do một phiếu bài tập chung cho cả lớp gần như chắc chắn nằm sai chỗ với phần lớn học sinh: quá dễ với vài em, quá khó với vài em khác, đúng tầm với một nhóm nhỏ ở giữa.</p><h2 id="scaffolding-trong-nhu-the-nao-​" tabindex="-1">Scaffolding trông như thế nào <a href="#scaffolding-trong-nhu-the-nao">​</a> <a class="header-anchor" href="#scaffolding-trong-nhu-the-nao-​" aria-label="Permalink to &quot;Scaffolding trông như thế nào [​](#scaffolding-trong-nhu-the-nao)&quot;">​</a></h2><p>Dạng hỗ trợVí dụChia nhỏ bài toán&quot;Trước hết tìm chiều cao. Rồi mới tính diện tích.&quot;Cho sẵn một phầnĐề cho sẵn hình vẽ, learner chỉ tập trung vào lập luậnCâu hỏi dẫn&quot;Hai tam giác này có góc nào bằng nhau không?&quot;Bài mẫu song songMột bài tương tự đã giải sẵn, đặt cạnh bài cần làmKhung câu trả lời&quot;Vì… nên… do đó…&quot; cho bài viếtThu hẹp lựa chọnBỏ bớt hai phương án rõ ràng sai để learner tập trung vào chỗ khó thậtĐiểm chung: chúng <strong>không làm hộ phần khó</strong>. Chúng gỡ những thứ đang chiếm chỗ trong đầu learner để phần khó thật sự có chỗ mà xử lý.</p><h2 id="go-gian-giao-moi-la-phan-kho-​" tabindex="-1">Gỡ giàn giáo mới là phần khó <a href="#go-gian-giao-moi-la-phan-kho">​</a> <a class="header-anchor" href="#go-gian-giao-moi-la-phan-kho-​" aria-label="Permalink to &quot;Gỡ giàn giáo mới là phần khó [​](#go-gian-giao-moi-la-phan-kho)&quot;">​</a></h2><p>Đây là chỗ scaffolding hay hỏng trong thực tế. Hỗ trợ dễ thêm vào và khó bỏ đi — nhất là khi learner đã quen với nó và tỏ ra khó chịu khi bị lấy mất. Nemo12 gỡ hỗ trợ theo tín hiệu kết quả, không theo lịch: khi learner làm đúng <strong>ổn định</strong> ở một mức hỗ trợ, mức tiếp theo được thử với ít hỗ trợ hơn. Nếu hụt, hệ thống lùi lại một bậc thay vì bỏ mặc. Điều này cũng giải thích vì sao hệ thống <strong>ghi lại việc learner có dùng gợi ý hay không</strong>. Làm đúng có gợi ý và làm đúng một mình là hai bằng chứng khác nhau về hai thứ khác nhau — gộp chúng lại là cách nhanh nhất để tưởng con đã vững trong khi con mới chỉ vững-khi-có-người-đỡ. Khi scaffold vẫn không đủ Nếu learner đã được hạ độ khó, đã có gợi ý, đã có bài mẫu mà vẫn không làm được — thêm scaffold nữa là sai hướng. Đó gần như luôn là dấu hiệu <strong>thiếu kiến thức nền</strong>, không phải thiếu hỗ trợ. Hệ thống chuyển sang truy ngược chuỗi kiến thức để tìm mắt xích hổng, thường nằm ở tận một hai lớp trước.</p><h2 id="vi-sao-đieu-nay-đang-quan-tam-voi-gia-đinh-​" tabindex="-1">Vì sao điều này đáng quan tâm với gia đình <a href="#vi-sao-đieu-nay-đang-quan-tam-voi-gia-đinh">​</a> <a class="header-anchor" href="#vi-sao-đieu-nay-đang-quan-tam-voi-gia-đinh-​" aria-label="Permalink to &quot;Vì sao điều này đáng quan tâm với gia đình [​](#vi-sao-đieu-nay-đang-quan-tam-voi-gia-đinh)&quot;">​</a></h2><p>Hai phản xạ tự nhiên khi con làm bài không được, và cả hai đều là scaffolding hỏng: <strong>Giảng lại từ đầu.</strong> Nếu con hụt ở một khâu cụ thể, giảng lại toàn bộ bài buộc con ngồi nghe 15 phút những thứ đã biết để tới được 2 phút cần thiết. Con mất tập trung trước khi tới được chỗ đó. <strong>Làm mẫu rồi bảo con làm y hệt.</strong> Con làm đúng bài đó, và không làm được bài tiếp theo. Vì thứ được truyền đi là <em>các bước của bài này</em>, không phải cách quyết định nên làm gì. Câu hỏi hữu ích hơn cả hai: <em>&quot;Con kẹt ở chỗ nào?&quot;</em> — rồi chỉ đỡ đúng chỗ đó. Scaffolding tốt để lại một learner làm được một mình. Scaffolding tệ để lại một learner cần được đỡ mãi mãi. <a href="/learning/retrieval-practice">Retrieval Practice — nhớ lại chủ động →</a></p>',10)])])}const f=h(g,[["render",c]]);export{s as __pageData,f as default};
